async function run(){await db.initialize();console.log("Database initialized.");const e={step:e=>console.log(`[Step] ${e}`),success:e=>console.log(`[Success] ${e}`),error:e=>console.error(`[Error] ${e}`)};console.log("Triggering market import...");try{const o=await importMarkets({ctx:e});console.log("Import result:",o);const r=await db.models.exchangeMarket.count();console.log(`Total exchangeMarket count in DB after import: ${r}`)}catch(e){console.error("Import failed with error:",e)}process.exit(0)}require("dotenv").config({path:"../.env"});require("./module-alias-setup.js");const{db:db}=require("@b/db"),importMarkets=require("./src/api/admin/finance/exchange/market/import.get.js").default;run();